Assume Assumptions~1, 2 and 3 hold. 
    The optimality gap under the two-set policy (alg:two-set) is bounded as 
    \begin{equation}
        R^{\textup{rel}} - R(\pi, \bm{S}_0) \leq O(1) \cdot \mathbb{P}\left[D^{\textup{OL}}_\infty \neq [N]\right].
    \end{equation}

Suppose there exists a function $V(x, D^{\textup{OL}}, D^{{{\bar{\pi}}^*}})$ and positive numbers $V_{\max}$ and $\overline{\eta}$ of constant orders such that for any $t\geq 0$,
    \begin{equation}

        0 \leq V(\Sigma_t) \leq V_{\max} \quad a.s.;
    \end{equation}
    if $V(\Sigma_{t}) > \overline{\eta}$,
    \begin{align}

        \mathbb{E}\big[V(\Sigma_{t+1}) - V(\Sigma_t) \,\big|\, \Sigma_t\big] &\leq -\gamma \\

         \mathbb{E}\big[(V(\Sigma_{t+1}) - V(\Sigma_t))^+  \,\big|\, \Sigma_t\big] &= O(1/\sqrt{N});
    \end{align}
    if $\overline{\eta}/2 < V(\Sigma_t) \leq \overline{\eta}$,
    \begin{equation}

        \mathbb{E}\big[(V(\Sigma_{t+1}) - V(\Sigma_t))^+  \,\big|\, \Sigma_t\big] = O(\exp(-C N)); 
    \end{equation}
    if $V(\Sigma_{t}) \leq \overline{\eta}/2$,
    \begin{equation}

        \mathbb{P}\big[V(\Sigma_{t+1}) > \overline{\eta}/2  \,\big|\, \Sigma_t\big] = O(\exp(-C' N)), 
    \end{equation}
    where $\gamma, C, C'$ are positive constants. 
    Then we have 
    \begin{align}

        \mathbb{P}\left[V(\Sigma_{\infty}) > \overline{\eta}\right] = O(\exp(-C'' N)),   
    \end{align}
    where $C''$ is another positive constant.

Assume Assumptions~1, 2 and 3 hold. 
    For any time step $t$ and $D\subseteq [N]$, let $X_{t+1}'$ be the system state at time $t+1$ if the arms in $D$ follow the Unconstrained Optimal Control at time $t$, then we have
    \begin{align}

        \mathbb{E}\big[(h_W(X_{t+1}', D) - \rho_{w} h_W(X_t, D))^+ \,\big|\, X_t\big] &= O(1/\sqrt{N}) \quad a.s. \\

        \mathbb{P}\big[h_W(X_{t+1}', D) > \rho_{w} h_W(X_t, D) + r   \,\big|\, X_t\big] &= O(\exp(-C N r^2)) \quad a.s. \quad \forall r \geq 0,
    \end{align}
    where $\rho_{w} = 1 - 1/(2\lambda_W)$, and $C$ is a positive constant. 
    In addition, for any $D, D'\subseteq [N]$, 
    \begin{align}

        h_W(x, D) &\geq \frac{1}{|\mathbb{S}|^{1/2}} \left\lVert x(D) - m(D)\mu^*\right\rVert_1 \\

        \left\lvert h_W(x, D) - h_W(x, D')\right\rvert &\leq 2\lambda_W^{1/2} (m(D'\backslash D) + m(D\backslash D')),
    \end{align}
    The same inequalities hold for $h_U$ with the Unconstrained Optimal Control and $W$ replaced by the Optimal Local Control and $U$. We omit the details here.

Suppose Assumptions~1, 2 and 3 hold. Let $\pi$ be the two-set policy in alg:two-set with a pair of feasibility-ensuring $(\eta, \epsilon_N^{\text{fe}})$ such that $\eta=\Theta(1)$ and $\epsilon_N^{\text{fe}}=O(1/N)$. Then for some $C > 0$ independent of $N$:
    \begin{equation}
        R^{\textup{rel}} - R(\pi, \bm{S}_0) = O\big(\exp(-CN)\big).
    \end{equation}
